"""Manually mapped exact model columns checked on KTM-authored manual page images.
Dealer-hosted editions; mirror authenticity and market reconciliation remain pending.
"""
import pathlib,sys,hashlib,json,re,datetime
src=pathlib.Path(sys.argv[1]);out=pathlib.Path(__file__).parent/'ktm';out.mkdir(exist_ok=True);manifest=[]
jobs=[('125 SX','2005_ktm_125_250_sx.pdf','https://mobil.ktmshop.se/bike-manuals/6101E9_OM_EN.pdf','3.211.38',49,47,'124.8','54 / 54.5','1471 ± 10','390','7.5','23:73',['13:32','15:30','17:28','19:26','21:25'],'NGK BR9 EVX','4.2'),('250 SX','2005_ktm_125_250_sx.pdf','https://mobil.ktmshop.se/bike-manuals/6101E9_OM_EN.pdf','3.211.38',53,51,'249','66.4 / 72','1475 ± 10','385','7.5','26:72',['14:28','16:26','18:24','21:24','22:21'],'NGK BR8 ECM','4.4'),('450 SX Racing','2005_ktm_450_525_sx.pdf','https://www.ktmshop.se/bike-manuals/8500E1_OM_EN.pdf','3.211.39',53,56,'449','95 / 63.4','1481 ± 10','380','7','33:76',['16:32','18:30','20:28','22:26'],'NGK DCPR 8 E','4.6'),('525 SX Racing','2005_ktm_450_525_sx.pdf','https://www.ktmshop.se/bike-manuals/8500E1_OM_EN.pdf','3.211.39',53,56,'510','95 / 72','1481 ± 10','380','7','33:76',['16:32','18:30','20:28','22:26'],'NGK DCPR 8 E','4.6')]
for model,file,url,rev,engine,chassis,disp,bore,wb,gc,fuel,primary,gears,plug,spring in jobs:
 sha=hashlib.sha256((src/file).read_bytes()).hexdigest();facts=[]
 def add(label,value,unit,page):
  facts.append(dict(id='ktm-2005-'+re.sub('[^a-z0-9]+','-',model.lower())+'-'+re.sub('[^a-z0-9]+','-',label.lower()).strip('-'),property='dimensions' if unit=='mm' else 'other',joint=label,value=value,unit=unit,conditions=['Exact 2005 stock SX column; EXC and MXC columns excluded.','English multi-market OEM-authored manual hosted by KTM dealer; US applicability and mirror authenticity require independent review.'],source_url=url,locator=f'PDF page {page}; printed page {page-1}',document_sha256=sha,document_revision='2005 KTM Owner’s Manual '+rev,retrieved_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),review_status='PENDING',review_note='Selected engine and chassis columns visually inspected. Dealer mirror; independent authenticity, market and conflict review required.',reviewer_id='codex-source-inspection-20261016',approval_reference=None))
 for label,val,unit in [('Engine / Displacement',disp,'cm³'),('Engine / Bore / stroke',bore,'mm'),('Drive train / Primary gear tooth ratio',primary,None),('Drive train / Number of gears',str(len(gears)),None),('Electrical / Spark plug',plug,None)]:add(label,val,unit,engine)
 for n,val in enumerate(gears,1):add(f'Drive train / Gear {n} tooth ratio',val,None,engine)
 for label,val,unit in [('Dimension / Wheelbase',wb,'mm'),('Dimension / Seat height unloaded','925','mm'),('Dimension / Ground clearance unloaded',gc,'mm'),('Frame / Fuel tank capacity',fuel,'L'),('Suspension / Front wheel travel','300','mm'),('Suspension / Rear wheel travel','335','mm'),('Suspension / Standard fork spring rate',spring,'N/mm')]:add(label,val,unit,chassis)
 target=dict(manufacturer='KTM',model=model,model_year=2005,variant='standard',region='US');name='2005-'+re.sub('[^a-z0-9]+','-',model.lower())+'-candidates.json'
 (out/name).write_text(json.dumps(dict(target=target,assemblies=[],parts=[],facts=facts,mappings=[]),ensure_ascii=False,indent=2)+'\n');manifest.append(dict(target=target,file='ktm/'+name,source_url=url,document_sha256=sha,facts=len(facts),status='CANDIDATES_ONLY_DEALER_MIRROR',database_imported=False,source_pdf_redistributed=False))
(out/'source-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print('models',len(manifest),'facts',sum(m['facts'] for m in manifest))
